    # its own color across the full row and column; preserve existing marks.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            color = grid[r][c]
            if color not in (1, 2, 4, 6, 8):
                continue
            if grid[r-1][c] == grid[r+1][c] == grid[r][c-1] == grid[r][c+1] == 3:
                for x in range(w):
                    if out[r][x] == 0:
                        out[r][x] = color
                for y in range(h):
                    if out[y][c] == 0:
                        out[y][c] = color
    return out
