 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            color = grid[r][c]
            if color in (1, 2, 4, 5, 6, 8) and all(grid[y][x] == 3 for y, x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))):
                centers.append((r, c, color))
    rows, cols = {}, {}
    for r, c, color in centers:
        rows[r] = color
        cols[c] = color
    for r, color in rows.items():
        for c in range(w):
            if grid[r][c] == 0:
                out[r][c] = color
    for c, color in cols.items():
        for r in range(h):
            if grid[r][c] == 0 or (grid[r][c] == 3 and r in rows):
                out[r][c] = color
    return out
